using DbConnect.Models;
using DbConnect.Services;
using DbConnect.ViewModels;

namespace DbConnect.Tests.ProviderConformance;

/// <summary>Truncate, Empty, Rename and Duplicate against live servers (§1.7).</summary>
public sealed class ExplorerObjectActionsConformanceTests : MainWindowTestBase
{
    private static string Create(string provider, string table) => provider switch
    {
        "PostgreSQL" => $"CREATE TABLE {table} (id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, a int NOT NULL CHECK (a > 0), g int GENERATED ALWAYS AS (a * 2) STORED)",
        "MySQL" => $"CREATE TABLE {table} (id int AUTO_INCREMENT PRIMARY KEY, a int NOT NULL CHECK (a > 0), g int GENERATED ALWAYS AS (a * 2) STORED)",
        _ => $"CREATE TABLE {table} (id int IDENTITY(1,1) PRIMARY KEY, a int NOT NULL CONSTRAINT ck_a CHECK (a > 0), g AS (a * 2) PERSISTED)"
    };

    [Theory]
    [InlineData("PostgreSQL")]
    [InlineData("MySQL")]
    [InlineData("SQL Server")]
    [Trait("Category", "Integration")]
    public async Task DuplicateRenameTruncateAndEmpty_WorkOnTheServer(string providerName)
    {
        var cs = ProviderConformanceFixture.GetEnvironmentConnectionString(providerName);
        if (string.IsNullOrWhiteSpace(cs)) return;
        var provider = new DatabaseService().GetProvider(providerName);
        var suffix = Guid.NewGuid().ToString("N")[..8];
        var schema = providerName == "MySQL" ? null : $"rain_act_{suffix}";
        var name = $"rain item.{suffix}";
        var quote = provider.Capabilities.QuoteIdentifier;
        string Q(string table) => schema == null ? quote(table) : quote(schema) + "." + quote(table);
        async Task<long> Count(string table) =>
            Convert.ToInt64((await provider.ExecuteQueryAsync(cs, $"SELECT count(*) FROM {Q(table)}")).ObjectRows[0][0]);

        var vm = CreateMainWindowViewModel(new DatabaseService());
        var root = new SchemaNode { Name = "db", Type = SchemaNodeType.Database };
        var node = new SchemaNode { Name = name, RawName = name, Type = SchemaNodeType.Table, SchemaName = schema };
        root.Children.Add(node);
        vm.ActiveSessions[root] = new DatabaseSession(new ConnectionInfo { Name = "live", Provider = providerName, ConnectionString = cs }, provider);
        vm.ShowDestructiveActionConfirmDialog = _ => Task.FromResult(true);
        try
        {
            if (schema != null) await provider.ExecuteNonQueryAsync(cs, $"CREATE SCHEMA {quote(schema)}");
            await provider.ExecuteNonQueryAsync(cs, Create(providerName, Q(name)));
            await provider.ExecuteNonQueryAsync(cs, $"INSERT INTO {Q(name)} (a) VALUES (1), (2), (3)");

            await vm.Explorer.DuplicateAsync(node, includeData: true);
            Assert.False(vm.StatusHasError, vm.StatusMessage);
            var copy = name + "_copy1";
            Assert.Equal(3, await Count(copy));
            Assert.Equal(12L, Convert.ToInt64((await provider.ExecuteQueryAsync(cs, $"SELECT sum(g) FROM {Q(copy)}")).ObjectRows[0][0]));
            await provider.ExecuteNonQueryAsync(cs, $"INSERT INTO {Q(copy)} (a) VALUES (4)");
            await Assert.ThrowsAnyAsync<Exception>(() => provider.ExecuteNonQueryAsync(cs, $"INSERT INTO {Q(copy)} (a) VALUES (0)"));

            var copyNode = new SchemaNode { Name = copy, RawName = copy, Type = SchemaNodeType.Table, SchemaName = schema };
            root.Children.Add(copyNode);
            vm.Explorer.PromptForName = (_, _, _) => Task.FromResult<string?>(copy + " renamed");
            await vm.Explorer.RenameAsync(copyNode);
            Assert.False(vm.StatusHasError, vm.StatusMessage);
            Assert.Equal(4, await Count(copy + " renamed"));

            await vm.Explorer.TruncateAsync(node);
            Assert.False(vm.StatusHasError, vm.StatusMessage);
            Assert.Equal(0, await Count(name));

            var renamedNode = new SchemaNode { Name = copy + " renamed", RawName = copy + " renamed", Type = SchemaNodeType.Table, SchemaName = schema };
            root.Children.Add(renamedNode);
            await vm.Explorer.EmptyAsync(renamedNode);
            Assert.False(vm.StatusHasError, vm.StatusMessage);
            Assert.Equal(0, await Count(copy + " renamed"));
        }
        finally
        {
            foreach (var table in new[] { name, name + "_copy1", name + "_copy1 renamed" })
                try { await provider.ExecuteNonQueryAsync(cs, $"DROP TABLE {Q(table)}"); } catch { }
            if (schema != null) try { await provider.ExecuteNonQueryAsync(cs, $"DROP SCHEMA {quote(schema)}"); } catch { }
        }
    }
}
